using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;
namespace GearLab {
 public static class WaveProjectMigration {
  public static bool IsWaveFile(string path){return path.EndsWith(".wave.json",StringComparison.OrdinalIgnoreCase);}
  public static Parameters Read(string path){if(new FileInfo(path).Length>65536)throw new Exception("Проект волнового редуктора слишком большой.");var w=CADDocument.Serializer().Deserialize<WaveParameters>(File.ReadAllText(path));w.Validate();var p=Engine.Starter(4);p.Ratio=w.Ratio;p.Module=w.Module;p.Thickness=w.Thickness;p.WaveWall=w.Wall;p.Wall=w.RingWall;p.Shaft=w.Bore;p.OutputShaft=w.OutputBore;p.Clearance=w.Clearance;p.WaveBearingWall=w.BearingWall;p.InputTorque=w.InputTorque;p.InputRpm=w.InputRpm;p.Efficiency=w.Efficiency;p.LoadTorque=w.LoadTorque;p.Overall=0;p.AutoFit=false;return p;}
 }
 public static class WaveExactExport {
  public static void Write(Parameters p,string path,CADKernel kernel,IEnumerable<string> ids=null){var doc=WaveFastModel.From(p).Document();doc.Features[0].Id="wave";var result=Engine.Calculate(p);result.Model=CadBuilder.Build(result);var motor=new CadAssembly();motor.Parts.AddRange(result.Model.Parts.Where(x=>x.Reference));string stage=Path.Combine(kernel.Folder,"motor.step");if(motor.Parts.Count>0){StepExport.Write(motor,stage);var f=CADDocument.ImportStep(File.ReadAllBytes(stage),"Мотор: габаритный образец").Features[0];f.Id="motor";doc.Features.Add(f);}var shaft=CADTools.Feature("cylinder");shaft.Id="wave_input";shaft.Values["Radius"]=Engine.N(p.Shaft/2);double depth=Math.Max(2,p.Wall*.75)+p.Clearance+8;shaft.Values["Height"]=Engine.N(depth+2*p.Thickness+p.Clearance);doc.Features.Add(shaft);doc.Features.Add(new CADFeature{Id="input_move",Kind="move",Target=shaft.Id,Values=new Dictionary<string,string>{{"Z",Engine.N(-depth)}}});
   var selected=ids==null?null:ids.ToArray();if(selected==null&&p.ExportScope==1)selected=new[]{"wave_ring","wave_flex","wave_output","wave_generator","wave_bearing"};if(selected==null&&p.ExportScope==2)selected=new[]{"wave_ring","wave_flex","wave_output"};var extra=selected==null?null:new Dictionary<string,object>{{"Parts",selected}};kernel.Run(doc,"export_step",path,null,null,extra);
  }
 }
 public partial class MainForm {
  static int WaveQuickRatio(int key){return key==8?20:key==9?30:key==20?50:key==30?80:100;}
  readonly CADKernel waveExportKernel=new CADKernel();bool waveExportBusy;Button waveCancel;
  async void ExportWaveStep(IEnumerable<string> selected=null,string chosenPath=null){if(waveExportBusy||!ReadControls())return;Recalculate();if(!result.Valid||!result.Model.Valid)return;string path=chosenPath??dialogs.Save(this,"step","Редуктор_Волновой_"+Engine.N(p.Ratio)+"к1.step");if(path==null)return;var snapshot=Engine.Clone(p);waveExportBusy=true;canvas.ShowMotion=false;string temporary=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),".gearlab-wave-"+Guid.NewGuid().ToString("N")+".step");try{if(waveCancel==null){waveCancel=new Button{Text="Отменить STEP",Width=130,Height=32};waveCancel.Click+=(s,e)=>waveExportKernel.Cancel();step.Parent.Controls.Add(waveCancel);}waveCancel.Visible=true;footer.Text="Экспорт точного STEP… Предпросмотр и камера остаются доступны.";await Task.Factory.StartNew(()=>WaveExactExport.Write(snapshot,temporary,waveExportKernel,selected));if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);if(!IsDisposed)footer.Text="STEP сохранён: "+path;}catch(Exception ex){if(!IsDisposed)footer.Text="STEP не сохранён: "+ex.GetBaseException().Message;}finally{if(File.Exists(temporary))File.Delete(temporary);waveExportBusy=false;if(!IsDisposed&&waveCancel!=null)waveCancel.Visible=false;}}
  void InitializeWaveExport(){FormClosing+=(s,e)=>{if(waveExportBusy){footer.Text="Дождитесь STEP-экспорта или нажмите «Отменить STEP».";e.Cancel=true;}};FormClosed+=(s,e)=>waveExportKernel.Dispose();}
 }
}
